use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabaseLimits,SqliteSnapshotControl,export_sqlite_database,import_sqlite_database}};

fn words()->Vec<u64>{#[derive(value_derive::FromValue)]#[value(rename_all="camelCase")]struct Words{binary64_bits:Vec<String>}let fixture:Words=dsl::json::from_json_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔢️words/🔣️.json")).unwrap();fixture.binary64_bits.iter().map(|word|u64::from_str_radix(word,16).unwrap()).collect()}
fn word_snapshot(bits:u64)->GltfSnapshot{let mut snapshot=fixture();let value=f64::from_bits(bits);snapshot.document.nodes[0].matrix=Some([value;16]);snapshot.document.nodes[0].translation=Some([value;3]);snapshot.document.nodes[0].rotation=Some([value;4]);snapshot.document.nodes[0].scale=Some([value;3]);snapshot.document.nodes[0].weights=vec![value];snapshot.document.meshes[0].weights=vec![value];snapshot.document.accessors[0].min=Some(vec![value]);snapshot.document.accessors[0].max=Some(vec![value]);let material=&mut snapshot.document.materials[0];material.emissive_factor=[value;3];material.alpha_cutoff=value;let pbr=material.pbr_metallic_roughness.as_mut().unwrap();pbr.base_color_factor=[value;4];pbr.metallic_factor=value;pbr.roughness_factor=value;material.normal_texture.as_mut().unwrap().scale=value;material.occlusion_texture.as_mut().unwrap().strength=value;snapshot.document.extras=Some(GltfJson::Object(vec![("z first".into(),GltfJson::Number(value)),("a second".into(),GltfJson::Bool(true)),("duplicate".into(),GltfJson::Number(value)),("duplicate".into(),GltfJson::Null)]));if let GltfCameraProjection::Perspective(camera)=&mut snapshot.document.cameras[0].projection{camera.aspect_ratio=Some(value);camera.yfov=value;camera.zfar=Some(value);camera.znear=value;}if let GltfCameraProjection::Orthographic(camera)=&mut snapshot.document.cameras[1].projection{camera.xmag=value;camera.ymag=value;camera.zfar=value;camera.znear=value;}snapshot.document.nodes[0].mesh=Some(usize::MAX);snapshot.document.buffers[0].byte_length=usize::MAX;snapshot.document.samplers[0].mag_filter=Some(u64::MAX);snapshot}
fn independent(database:&semio_framework_os_kernel::sqlite_snapshot::SqliteDatabase,sql:&str)->semio_framework_os_kernel::sqlite_snapshot::SqliteDatabase{use std::{io::Write,process::{Command,Stdio}};let limits=SqliteDatabaseLimits::default();let bytes=export_sqlite_database(database,limits,&mut |_|true).unwrap();let script="const {Database}=require('bun:sqlite');const db=Database.deserialize(await Bun.stdin.bytes());if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('invalid semantic database');db.run(process.argv[1]);process.stdout.write(db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script,sql]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));import_sqlite_database(&output.stdout,limits,&mut |_|true).unwrap()}
#[test]
fn sqlite_snapshot_gltf_independent_sql_reserialization_preserves_ieee_words_unsigned_and_duplicate_extras(){for bits in words(){let snapshot=word_snapshot(bits);let limits=SqliteDatabaseLimits::default();let expected=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let database=independent(&expected,"SELECT 1");let restored=GltfSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored.document.nodes[0].matrix.unwrap()[0].to_bits(),bits);assert_eq!(restored.document.nodes[0].mesh,Some(usize::MAX));assert_eq!(restored.document.samplers[0].mag_filter,Some(u64::MAX));assert_eq!(restored.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),expected);}}
#[test]
fn sqlite_snapshot_gltf_erased_binary_and_text_preserve_every_owned_field(){use store::sqlite_snapshot::SnapshotEncoding;let codec=<GltfSnapshot as ArtifactSqliteSnapshot>::sqlite_codec();let dialect=semio_framework_os_kernel::io_schema::ArtifactDialect{artifact_kind:"s.stdio.gltf".into(),standard:"2.0".into(),subset:"*".into()};for bits in words(){let snapshot=word_snapshot(bits);let limits=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=(codec.import)(&snapshot.schema,&dialect,database.clone(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;let restored=(codec.export)(&snapshot.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;assert_eq!(restored,database);}}}
#[test]
fn sqlite_snapshot_gltf_rejects_independently_edited_ieee_conflict_and_unowned_relationship(){let snapshot=fixture();let limits=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for sql in["UPDATE gltf_material SET alpha_cutoff=0.75 WHERE id=1","UPDATE gltf_primitive_attribute SET ordinal=4 WHERE id=1","INSERT INTO gltf_scene_node VALUES(99,99,0,0,0)"]{let database=independent(&database,sql);assert!(GltfSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}}


fn fixture()->GltfSnapshot{dsl::json::from_json_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap()}

#[test]
fn sqlite_snapshot_gltf_exact_typed_guard_budget_and_cancellation(){use semio_framework_os_kernel::{io_schema::ArtifactDialect,sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotPhase}};let snapshot=fixture();let limits=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for(artifact_kind,standard,subset)in[("s.stdio.gltf","2.0","*"),("s.stdio.obj","2.0","*"),("s.stdio.gltf","1.0","*"),("s.stdio.gltf","2.0","camera")]{let dialect=ArtifactDialect{artifact_kind:artifact_kind.into(),standard:standard.into(),subset:subset.into()};assert_eq!(snapshot.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_ok(),artifact_kind=="s.stdio.gltf"&&standard=="2.0"&&subset=="*");}let mut wrong=database.clone();wrong.table_mut("gltf_document").unwrap().rows[0].values[1]=semio_framework_os_kernel::sqlite_snapshot::SqliteValue::Text("other".into());let dialect=ArtifactDialect{artifact_kind:"s.stdio.gltf".into(),standard:"2.0".into(),subset:"*".into()};assert!(snapshot.validate_sqlite_snapshot_subset(&dialect,&wrong,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());let mut large=snapshot.clone();large.document.asset.generator=Some("\"".repeat(65537));for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_ok());let small=SqliteDatabaseLimits{max_value_bytes:4096,..limits};assert!(large.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,small)).is_err());assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());}let small=SqliteDatabaseLimits{max_rows:1,..limits};assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,small)).is_err());assert!(GltfSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());let mut work=snapshot.clone();work.document.nodes=vec![GltfNode::default();600];let mut reached=false;let mut progress=|event:semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>=256{reached=true;false}else{true}};assert!(work.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut progress,limits)).is_err());assert!(reached);}


#[test]
fn sqlite_snapshot_gltf_full_typed_document_and_independent_buffers_reconstruct(){
 let snapshot=fixture();let limits=SqliteDatabaseLimits::default();
 let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();
 assert_eq!(database.table("gltf_primitive").unwrap().rows.len(),1);
 assert_eq!(database.table("gltf_accessor").unwrap().rows.len(),3);
 assert_eq!(database.table("gltf_resolved_buffer").unwrap().rows.len(),3);
 let bytes=export_sqlite_database(&database,limits,&mut |_|true).unwrap();
 let database=import_sqlite_database(&bytes,limits,&mut |_|true).unwrap();
 let restored=GltfSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();
 assert_eq!(restored,snapshot);
}

#[test]
fn sqlite_snapshot_gltf_independent_sql_mesh_accessor_material_and_buffer_edits(){
 use std::{io::Write,process::{Command,Stdio}};
 let snapshot=fixture();let limits=SqliteDatabaseLimits::default();
 let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();
 let bytes=export_sqlite_database(&database,limits,&mut |_|true).unwrap();
 let script=r#"const {Database}=require('bun:sqlite');const db=Database.deserialize(await Bun.stdin.bytes());if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('invalid semantic database');const row=db.query('SELECT m.name AS mesh,a.semantic,ac.name AS accessor,mat.name AS material FROM gltf_mesh m JOIN gltf_primitive p ON p.mesh_id=m.id JOIN gltf_primitive_attribute a ON a.primitive_id=p.id JOIN gltf_accessor ac ON ac.ordinal=a.accessor_index_low JOIN gltf_material mat ON mat.ordinal=p.material_index_low WHERE a.ordinal=0').get();if(row.mesh!=='Mesh'||row.semantic!=='POSITION'||row.accessor!=='Positions'||row.material!=='Material')throw Error('semantic join mismatch');db.run("UPDATE gltf_material SET name='Edited material' WHERE id=1");db.run('UPDATE gltf_resolved_byte SET value=17 WHERE buffer_id=1 AND ordinal=1');process.stdout.write(db.serialize());db.close();"#;
 let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();
 child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));
 let database=import_sqlite_database(&output.stdout,limits,&mut |_|true).unwrap();
 let restored=GltfSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();
 assert_eq!(restored.document.materials[0].name.as_deref(),Some("Edited material"));
 assert_eq!(restored.buffers[0],vec![0,17,1]);assert_eq!(restored.document.buffers[0].byte_length,64);
}

#[test]
fn sqlite_snapshot_gltf_actual_factory_exposes_owned_provider_and_structural_hash(){let codec=(crate::native_codecs()[0].codec)();assert!(codec.snapshot_sqlite.is_some());let spec=<GltfSnapshot as store::ArtifactPack>::record_spec().expect("owned GLTF record spec");assert_eq!(codec.pack_schema_hash,store::schema_hash(&spec));}

#[test]
fn sqlite_snapshot_gltf_emit_owned_review_assets(){let Ok(directory)=std::env::var("SEMIO_GLTF_REVIEW_DIR")else{return};let directory=std::path::Path::new(&directory);std::fs::create_dir_all(directory).unwrap();let demo=crate::engine::demo_gltf_snapshot();std::fs::write(directory.join("gltf.dsl.semio"),store::ArtifactDsl::print_dsl(&demo)).unwrap();std::fs::write(directory.join("gltf.pack.semio"),store::ArtifactPack::encode_pack(&demo)).unwrap();let codec=(crate::native_codecs()[0].codec)();std::fs::write(directory.join("gltf-hash.txt"),codec.pack_schema_hash.iter().map(|byte|format!("{byte:02x}")).collect::<String>()).unwrap();}

#[test]
fn sqlite_snapshot_gltf_empty_domain_tables_preserve_absence_and_present_empty_lists(){let mut snapshot:GltfSnapshot=dsl::json::from_json_str(include_str!("../../🧫️fixtures/🪶️sqlite/🌱️minimal/🔣️.json")).unwrap();let limits=SqliteDatabaseLimits::default();let before=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(before.tables.len(),57);assert_eq!(before.table("gltf_accessor").unwrap().rows.len(),0);let database=independent(&before,"SELECT 1");assert_eq!(GltfSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),snapshot);snapshot.document.accessors=vec![GltfAccessor{min:Some(Vec::new()),max:None,..Default::default()}];snapshot.document.extras=Some(GltfJson::Null);snapshot.buffers=vec![Vec::new()];let database=independent(&snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),"SELECT 1");let restored=GltfSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored,snapshot);assert_eq!(restored.document.accessors[0].min,Some(Vec::new()));assert_eq!(restored.document.accessors[0].max,None);}

#[test]
fn sqlite_snapshot_gltf_deep_owned_extras_erased_payloads_have_bounded_wire_depth(){use store::sqlite_snapshot::SnapshotEncoding;let mut snapshot=fixture();#[derive(value_derive::FromValue)]#[value(rename_all="camelCase")]struct Depth{json_depth:usize}let depth:Depth=dsl::json::from_json_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔢️words/🔣️.json")).unwrap();let mut extras=GltfJson::Number(f64::from_bits(0x7ff8000000000042));for _ in 0..depth.json_depth{extras=GltfJson::Array(vec![extras])}snapshot.document.extras=Some(extras);let limits=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let codec=(crate::native_codecs()[0].codec)().snapshot_sqlite.expect("actual GLTF owned provider");let dialect=semio_framework_os_kernel::io_schema::ArtifactDialect{artifact_kind:"s.stdio.gltf".into(),standard:"2.0".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=(codec.import)(&snapshot.schema,&dialect,database.clone(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;let restored=(codec.export)(&snapshot.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;assert_eq!(restored,database);}}
